// Serves pdf.js from the app's own origin (no CDN, no blob worker): copies the worker, the
// standard font files (reports that do not embed their fonts render with ragged spacing without
// them) and the wasm decoders from node_modules into public/pdfjs. The copy is gitignored and
// regenerated by predev/prebuild.
import { cpSync, existsSync, mkdirSync, rmSync } from "node:fs"
import { dirname, join } from "node:path"
import { fileURLToPath } from "node:url"

const root = join(dirname(fileURLToPath(import.meta.url)), "..")
const source = join(root, "node_modules", "pdfjs-dist")
const target = join(root, "public", "pdfjs")

if (!existsSync(source)) {
  console.warn("copy-pdfjs-assets: pdfjs-dist is not installed, skipping")
  process.exit(0)
}

rmSync(target, { recursive: true, force: true })
mkdirSync(target, { recursive: true })
cpSync(join(source, "legacy", "build", "pdf.worker.min.mjs"), join(target, "pdf.worker.min.mjs"))
cpSync(join(source, "standard_fonts"), join(target, "standard_fonts"), { recursive: true })
cpSync(join(source, "wasm"), join(target, "wasm"), { recursive: true })
console.log("copy-pdfjs-assets: copied pdf.js worker, standard fonts and wasm to public/pdfjs")
